import Synchronization

let current = Atomic<Frame?>(nil)

func publish(_ finished: Frame) {      // writer
    current.store(finished, ordering: .releasing)
}

func snapshot() -> Frame? {            // readers
    current.load(ordering: .acquiring)
}

