import Synchronization

struct Pair { var current = Frame.empty; var next = Frame.empty }
let buffers = Mutex(Pair())

func publish(_ finished: Frame) {
    buffers.withLock { $0.current = finished }   // swap under the lock
}
func snapshot() -> Frame { buffers.withLock { $0.current } }
